from urllib.parse import urlparse, urlencode

def build_url(base_url, path='', query_params={}):
    if not base_url.endswith('/'):
        base_url += '/'

    url = base_url

    if path:
        url += path.lstrip('/')

    if query_params:
        query_string = urlencode(query_params)
        url += '?' + query_string

    parsed = urlparse(url)
    if parsed.scheme in {'http', 'https'}:
        return url
    else:
        return None
